alter policy "contests_member_advanced_all" on public.contests using (exists (select 1 from public.business_members bm join public.businesses b on b.id = bm.business_id where bm.business_id = contests.business_id and bm.user_id = (select auth.uid()) and bm.role = any (array['owner'::business_member_role,'admin'::business_member_role,'manager'::business_member_role]) and b.business_tier <> 'standard'::business_tier)) with check (exists (select 1 from public.business_members bm join public.businesses b on b.id = bm.business_id where bm.business_id = contests.business_id and bm.user_id = (select auth.uid()) and bm.role = any (array['owner'::business_member_role,'admin'::business_member_role,'manager'::business_member_role]) and b.business_tier <> 'standard'::business_tier));
alter policy "enterprise_engagement_scoped_insert" on public.enterprise_engagement_events with check (coalesce((select profiles.is_admin from public.profiles where profiles.id = (select auth.uid())),false) or exists (select 1 from public.enterprise_partner_networks n join public.app_business_memberships m on m.business_id = n.owner_business_id where n.id = enterprise_engagement_events.network_id and m.user_id = (select auth.uid())));
alter policy "enterprise_engagement_scoped_read" on public.enterprise_engagement_events using (coalesce((select profiles.is_admin from public.profiles where profiles.id = (select auth.uid())),false) or exists (select 1 from public.enterprise_partner_networks n join public.app_business_memberships m on m.business_id = n.owner_business_id where n.id = enterprise_engagement_events.network_id and m.user_id = (select auth.uid())) or exists (select 1 from public.enterprise_partner_network_members nm join public.enterprise_partner_networks n on n.id = nm.network_id join public.app_business_memberships m on m.business_id = nm.partner_business_id where nm.network_id = enterprise_engagement_events.network_id and nm.status = 'active'::text and m.user_id = (select auth.uid())));
alter policy "enterprise_intelligence_events_scoped_read" on public.enterprise_intelligence_events using (is_platform_owner((select auth.uid())) or exists (select 1 from public.enterprise_partner_networks n join public.business_members bm on bm.business_id = n.owner_business_id where n.id = enterprise_intelligence_events.network_id and bm.user_id = (select auth.uid())) or exists (select 1 from public.enterprise_partner_network_members nm join public.business_members bm on bm.business_id = nm.partner_business_id where nm.network_id = enterprise_intelligence_events.network_id and nm.status = 'active'::text and bm.user_id = (select auth.uid())));
alter policy "enterprise_partner_network_metrics_scoped_read" on public.enterprise_partner_network_metrics using (is_platform_owner((select auth.uid())) or exists (select 1 from public.enterprise_partner_networks n where n.id = enterprise_partner_network_metrics.network_id and (exists (select 1 from public.business_members bm where bm.business_id = n.owner_business_id and bm.user_id = (select auth.uid())) or exists (select 1 from public.enterprise_partner_network_members nm join public.business_members bm on bm.business_id = nm.partner_business_id where nm.network_id = n.id and nm.status = 'active'::text and bm.user_id = (select auth.uid())))));
